{
  "type_map": {},
  "constraints": [
    {
      "id": "R1",
      "category": "count_semantics",
      "alternatives": [
        "(df['NUM_PKTS_UP_TO_128_BYTES'] + df['NUM_PKTS_128_TO_256_BYTES'] + df['NUM_PKTS_256_TO_512_BYTES'] + df['NUM_PKTS_512_TO_1024_BYTES'] + df['NUM_PKTS_1024_TO_1514_BYTES']) == (df['IN_PKTS'] + df['OUT_PKTS'])",
        "(df['NUM_PKTS_UP_TO_128_BYTES'] + df['NUM_PKTS_128_TO_256_BYTES'] + df['NUM_PKTS_256_TO_512_BYTES'] + df['NUM_PKTS_512_TO_1024_BYTES'] + df['NUM_PKTS_1024_TO_1514_BYTES']) <= (df['IN_PKTS'] + df['OUT_PKTS'])"
      ],
      "features": [
        "NUM_PKTS_UP_TO_128_BYTES",
        "NUM_PKTS_128_TO_256_BYTES",
        "NUM_PKTS_256_TO_512_BYTES",
        "NUM_PKTS_512_TO_1024_BYTES",
        "NUM_PKTS_1024_TO_1514_BYTES",
        "IN_PKTS",
        "OUT_PKTS"
      ],
      "rationale": "The sum of packet counts across all size categories should equal total packets if no packets exceed 1514 bytes, otherwise it should be less than or equal to total packets."
    },
    {
      "id": "R2",
      "category": "count_semantics",
      "alternatives": [
        "df['RETRANSMITTED_IN_PKTS'] <= df['IN_PKTS']"
      ],
      "features": [
        "RETRANSMITTED_IN_PKTS",
        "IN_PKTS"
      ],
      "rationale": "Retransmitted packets in the src->dst direction are a subset of all packets in that direction."
    },
    {
      "id": "R3",
      "category": "count_semantics",
      "alternatives": [
        "df['RETRANSMITTED_OUT_PKTS'] <= df['OUT_PKTS']"
      ],
      "features": [
        "RETRANSMITTED_OUT_PKTS",
        "OUT_PKTS"
      ],
      "rationale": "Retransmitted packets in the dst->src direction are a subset of all packets in that direction."
    },
    {
      "id": "R4",
      "category": "count_semantics",
      "alternatives": [
        "df['RETRANSMITTED_IN_BYTES'] <= df['IN_BYTES']"
      ],
      "features": [
        "RETRANSMITTED_IN_BYTES",
        "IN_BYTES"
      ],
      "rationale": "Retransmitted bytes in the src->dst direction are a subset of all bytes in that direction."
    },
    {
      "id": "R5",
      "category": "count_semantics",
      "alternatives": [
        "df['RETRANSMITTED_OUT_BYTES'] <= df['OUT_BYTES']"
      ],
      "features": [
        "RETRANSMITTED_OUT_BYTES",
        "OUT_BYTES"
      ],
      "rationale": "Retransmitted bytes in the dst->src direction are a subset of all bytes in that direction."
    }
  ]
}
